  "--dsw-alias-bg-overlay": "rgb(9 12 17 / 97.0%)",
  "--dsw-alias-bg-mask-1": "rgb(9 12 17 / 63.5%)",
  "--dsw-alias-bg-module-platform": "rgb(9 12 17 / 93.0%)",
  "--dsw-specific-sidebar-fill": "rgb(9 12 17 / 63.5%)",
  "--dsw-alias-border-l1": "rgb(242 181 68 / 18%)",
  "--dsw-alias-border-l2": "rgb(242 181 68 / 34%)",
