/* --- module state -------------------------------------------------------- */

/* The static stylesheet and the solved glass live in two tags: the glass is
   rewritten on every step of the immersion dial, and rewriting the whole
   stylesheet for it would drag ~100 KiB of text through the CSS parser per
   frame. */
var skinTag = null;
var veilTag = null;
var tokenDisposer = null;
var themeRef;
var state = { index: 0, open: false, immersion: DEFAULT_IMMERSION };
/** Which wallpaper the warmer has already decoded, so it does not do it twice. */
var warmRef = null;
var listeners = new Set();

/* --- the immersion interpolation ----------------------------------------- */

/**
 * Alpha for one veil at one immersion.
 *
 * This single line is the whole interpolation; build-client.mjs holds its own
 * copy for the verification step. It is kept this trivial on purpose so the two
 * cannot drift.
 */
function alphaAt(range, immersion) {
  var t = Math.min(100, Math.max(0, immersion)) / 100;
  return range.max - (range.max - range.min) * t;
}

/** Format one veil at one immersion as a CSS colour. */
function rgbaAt(range, immersion) {
  return (
    "rgb(" +
    range.rgb[0] +
    " " +
    range.rgb[1] +
    " " +
    range.rgb[2] +
    " / " +
    (alphaAt(range, immersion) * 100).toFixed(1) +
    "%)"
  );
}

/** Every surface token for one wallpaper at one immersion. */
function tokensFor(wallpaper, immersion) {
  var out = {};
  var token;
  for (token in wallpaper.surfaces) {
    out[token] = {
      light: rgbaAt(wallpaper.surfaces[token].light, immersion),
      dark: rgbaAt(wallpaper.surfaces[token].dark, immersion),
    };
  }
  for (token in wallpaper.fixed) out[token] = wallpaper.fixed[token];
  return out;
}

/** The two glass custom properties for one wallpaper at one immersion. */
function glassFor(wallpaper, immersion) {
  return {
    dark: rgbaAt(wallpaper.glass.dark, immersion),
    light: rgbaAt(wallpaper.glass.light, immersion),
  };
}

/** The solved glass as CSS custom properties, for the small dynamic tag. */
function veilCss(wallpaper, immersion) {
  var glass = glassFor(wallpaper, immersion);
  return (
    ":root{--dsh-amiya-glass-dark:" +
    glass.dark +
    ";--dsh-amiya-glass-light:" +
    glass.light +
    ";}"
  );
}

/* --- contrast, for the live readout -------------------------------------- */

function linearize(channel) {
  var c = channel / 255;
  return c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
}

function luminance(rgb) {
  return 0.2126 * linearize(rgb[0]) + 0.7152 * linearize(rgb[1]) + 0.0722 * linearize(rgb[2]);
}

function contrastRatio(a, b) {
  var la = luminance(a);
  var lb = luminance(b);
  var hi = Math.max(la, lb);
  var lo = Math.min(la, lb);
  return (hi + 0.05) / (lo + 0.05);
}

/** Composite a parsed veil over the picture's mean colour, as CSS does. */
function compositeOver(meanRgb, parsed) {
  return [
    parsed.alpha * parsed.rgb[0] + (1 - parsed.alpha) * meanRgb[0],
    parsed.alpha * parsed.rgb[1] + (1 - parsed.alpha) * meanRgb[1],
    parsed.alpha * parsed.rgb[2] + (1 - parsed.alpha) * meanRgb[2],
  ];
}

/** Parse the two colour forms the token layer produces. */
function parseCss(value) {
  var fn = /^rgb\(\s*(\d+)\s+(\d+)\s+(\d+)\s*\/\s*([\d.]+)%\s*\)$/.exec(value);
  if (fn !== null) {
    return { rgb: [Number(fn[1]), Number(fn[2]), Number(fn[3])], alpha: Number(fn[4]) / 100 };
  }
  var hex = /^#([0-9a-fA-F]{6})$/.exec(value);
  if (hex !== null) {
    var n = parseInt(hex[1], 16);
    return { rgb: [(n >> 16) & 255, (n >> 8) & 255, n & 255], alpha: 1 };
  }
  return null;
}

/** Which palette is in force right now. */
function currentMode() {
  if (themeRef === undefined) return "dark";
  try {
    return themeRef.getTheme().active.colorScheme === "light" ? "light" : "dark";
  } catch (error) {
    return "dark";
  }
}

/**
 * The worst measured contrast across every surface class for one wallpaper at
 * one immersion, in the palette currently in force. This is what the picker
 * shows, so the dial's tradeoff is visible rather than discovered.
 */
function contrastFor(wallpaper, immersion) {
  var mode = currentMode();
  /* Read the ink that is actually in force, not a static guess: the picker reports
     the contrast the reader really gets. */
  var inkValue =
    wallpaper.inkVars === undefined
      ? undefined
      : wallpaper.inkVars[mode]["--dsh-amiya-ink" + (mode === "light" ? "-l" : "")];
  var inkParsed = inkValue === undefined ? null : parseCss(inkValue);
  var label = inkParsed === null ? LABEL_RGB[mode] : inkParsed.rgb;
  var tokens = tokensFor(wallpaper, immersion);
  var glass = glassFor(wallpaper, immersion);
  var values = [
    tokens["--dsw-alias-bg-base"],
    tokens["--dsw-alias-bg-layer-1"],
    tokens["--dsw-alias-bg-layer-2"],
    tokens["--dsw-alias-bg-overlay"],
    tokens["--dsw-specific-sidebar-fill"],
    glass[mode],
  ];
  var worst = Number.POSITIVE_INFINITY;
  for (var i = 0; i < values.length; i += 1) {
    var parsed = parseCss(values[i]);
    if (parsed === null) continue;
    var ratio = contrastRatio(compositeOver(wallpaper.mean, parsed), label);
    if (ratio < worst) worst = ratio;
  }
  return worst === Number.POSITIVE_INFINITY ? 0 : worst;
}

/* --- stylesheet ---------------------------------------------------------- */

/**
 * Mount the skin stylesheet plus an empty glass tag, both plugin-owned. The
 * `data-plugin-css` ids are what the client HMR driver uses to retract the tags,
 * so they are registered exactly the way the shipped client bundles register
 * theirs.
 * @returns {() => void} disposer removing both tags
 */
function mountStyles() {
  if (typeof document === "undefined") return function () {};
  var skinId = PACKAGE + "/amiya-wallpaper.css";
  var veilId = PACKAGE + "/amiya-wallpaper.glass.css";
  var skinSelector = "style[data-plugin-css=" + JSON.stringify(skinId) + "]";
  var veilSelector = "style[data-plugin-css=" + JSON.stringify(veilId) + "]";

  skinTag = document.querySelector(skinSelector);
  if (skinTag === null) {
    skinTag = document.createElement("style");
    skinTag.dataset.plugin = PACKAGE;
    skinTag.dataset.pluginCss = skinId;
    document.head.appendChild(skinTag);
  }
  skinTag.textContent = CSS;

  veilTag = document.querySelector(veilSelector);
  if (veilTag === null) {
    veilTag = document.createElement("style");
    veilTag.dataset.plugin = PACKAGE;
    veilTag.dataset.pluginCss = veilId;
    document.head.appendChild(veilTag);
  }

  return function () {
    skinTag = null;
    veilTag = null;
    var tags = document.querySelectorAll(
      skinSelector + "," + veilSelector,
    );
    for (var i = 0; i < tags.length; i += 1) {
      if (tags[i].parentNode !== null) tags[i].parentNode.removeChild(tags[i]);
    }
  };
}

/** Rewrite the small glass tag for this wallpaper and immersion. */
function applyVeil(wallpaper, immersion) {
  if (veilTag === null || typeof document === "undefined") return;
  veilTag.textContent = veilCss(wallpaper, immersion);
}

/**
 * Prefer the stylesheet this package's host half serves over the copy baked into
 * this bundle.
 *
 * The host reads `assets/skin.css` from disk on every request, so a corrected
 * stylesheet takes effect on a page reload. The embedded copy is what the module
 * graph snapshotted at process start, so relying on it alone would mean a CSS fix
 * could not land without restarting DSH — and the stylesheet is exactly the part
 * of a skin that gets iterated on. If the route is missing or answers with
 * something unexpected, the embedded copy stands.
 */
function refreshStylesFromRoute() {
  if (typeof fetch !== "function") return;
  fetch(ROUTE + "/assets/skin.css", { cache: "no-store" })
    .then(function (response) {
      return response.ok ? response.text() : null;
    })
    .then(function (text) {
      if (text === null || text.length < 1024) return;
      CSS = text;
      if (skinTag !== null) skinTag.textContent = CSS;
      var wallpaper = WALLPAPERS[state.index];
      if (wallpaper !== undefined) applyVeil(wallpaper, state.immersion);
    })
    .catch(function () {
      /* No route, no network: the embedded stylesheet is already applied. */
    });
}

/* --- wallpaper painting -------------------------------------------------- */

/**
 * Read the persisted choice, falling back to the first wallpaper.
 *
 * The stored value is the wallpaper's id, which survives a re-import that reorders the set;
 * a bare ordinal written by an earlier build is still understood.
 */
function readIndex() {
  try {
    var stored = window.localStorage.getItem(STORAGE_KEY);
    if (stored !== null) {
      for (var i = 0; i < WALLPAPERS.length; i += 1) {
        if (WALLPAPERS[i].id === stored) return i;
      }
      var ordinal = Number(stored);
      if (Number.isInteger(ordinal) && ordinal >= 0 && ordinal < WALLPAPERS.length) {
        return ordinal;
      }
    }
  } catch (error) {
    /* Private mode or blocked storage: the first wallpaper is a fine default. */
  }
  return 0;
}

/** Persist the chosen wallpaper. The id is stored so a re-import cannot shift the choice. */
function persistIndex(index) {
  var wallpaper = WALLPAPERS[index];
  if (wallpaper !== undefined) writeStored(STORAGE_KEY, wallpaper.id);
}

/** Read the persisted immersion, clamped to the dial's range. */
function readImmersion() {
  try {
    var stored = Number(window.localStorage.getItem(IMMERSION_KEY));
    if (Number.isFinite(stored) && stored >= 0 && stored <= 100) return Math.round(stored);
  } catch (error) {
    /* Fall through to the shipped default. */
  }
  return DEFAULT_IMMERSION;
}

/** Persist a value, tolerating a storage-denied browser. */
function writeStored(key, value) {
  try {
    window.localStorage.setItem(key, String(value));
  } catch (error) {
    /* Not fatal: the choice simply does not survive a reload. */
  }
}

/**
 * Stack this wallpaper's surface layer onto the active theme.
 *
 * `overrideTokens` replaces the layer for a given source on each call, so the
 * previous disposer must be released first — otherwise the layer would outlive
 * this plugin's fiber and keep tinting the interface after unload.
 */
function applyTokens(wallpaper, immersion) {
  if (typeof document === "undefined" || wallpaper.veilVars === undefined) return;
  var root = document.documentElement;
  var modes = ["dark", "light"];
  for (var i = 0; i < modes.length; i += 1) {
    var values = wallpaper.veilVars[modes[i]];
    for (var name in values) root.style.setProperty(name, rgbaAt(values[name], immersion));
  }
  /* The adaptive ink: a tinted text colour per palette, solved at build time for
     this picture. It arrives as custom properties for the same reason the veils do —
     it has to be correct even on the very first frame, before any service answers.

     This is not the old flip. That one forced one polarity on both palettes, so a
     white panel got white text. Here the polarity follows the palette and the
     lightness is solved against the worst surface the text can land on, including
     the near-opaque plane a dialog paints. */
  var inkVars = wallpaper.inkVars;
  if (inkVars !== undefined) {
    for (var j = 0; j < modes.length; j += 1) {
      var inkSet = inkVars[modes[j]];
      for (var inkName in inkSet) root.style.setProperty(inkName, inkSet[inkName]);
    }
  }
}

/**
 * The four label colours to render, in one palette mode.
 *
 * The palette's own polarity comes first, and is kept unless it actually fails.
 * That ordering matters: one label token is the text colour on many different
 * backgrounds, and only some of them are this skin's surfaces. A code panel's
 * background follows the palette's layer tokens, not the wallpaper, so a colour
 * chosen from the wallpaper's luminance can be exactly wrong for it — which is how
 * a white code panel ended up with white text. The palette already pairs every
 * surface with a legible label; the flip exists only to rescue the case the palette
 * cannot know about, which is the picture showing through at high immersion.
 *
 * @param {Array<{rgb: number[], alpha: number}>} surfaces
 * @param {number[]} meanRgb
 * @param {'dark' | 'light'} mode
 */
function pickLabelPolarity(surfaces, meanRgb, mode) {
  var palette = mode === "light" ? LABEL_SETS.dark : LABEL_SETS.light;
  var alternative = mode === "light" ? LABEL_SETS.light : LABEL_SETS.dark;
  var paletteWorst = worstLabelContrast(surfaces, meanRgb, palette[0]);
  if (paletteWorst >= 4.5) return palette;
  var alternativeWorst = worstLabelContrast(surfaces, meanRgb, alternative[0]);
  /* Only for a clear win: an ambiguous backdrop keeps the palette's pairing. */
  return alternativeWorst > paletteWorst + 1.5 ? alternative : palette;
}

/** Worst contrast one label colour achieves across the surfaces. */
function worstLabelContrast(surfaces, meanRgb, hex) {
  var primary = parseCss(hex);
  if (primary === null) return 0;
  var worst = Number.POSITIVE_INFINITY;
  for (var j = 0; j < surfaces.length; j += 1) {
    var ratio = contrastRatio(compositeOver(meanRgb, surfaces[j]), primary.rgb);
    if (ratio < worst) worst = ratio;
  }
  return worst === Number.POSITIVE_INFINITY ? 0 : worst;
}

/**
 * The cut that is actually on screen right now.
 *
 * The stylesheet switches between the 16:9 and the 3:4 asset by aspect ratio, so only one of
 * them is ever visible; warming the wrong one would cost bandwidth and decode time for nothing.
 */
function visibleCut(wallpaper) {
  var portrait =
    typeof window.matchMedia === "function" &&
    window.matchMedia("(max-aspect-ratio: 3 / 2)").matches;
  return ROUTE + "/" + (portrait ? wallpaper.narrow : wallpaper.wide);
}

/**
 * Fetch and decode the wallpaper the quick-step would land on.
 *
 * Called after every paint, so a press of the step button swaps between two already-decoded
 * bitmaps instead of falling back to the 32px placeholder while the file travels. One
 * neighbour only: decoded 2560x1440 bitmaps are ~14 MB each, so warming the whole set would
 * trade a visible flash for ~170 MB of resident memory.
 */
function warmNeighbour() {
  if (typeof Image !== "function" || WALLPAPERS.length < 2) return;
  var next = WALLPAPERS[(state.index + 1) % WALLPAPERS.length];
  if (next === undefined || next.id === warmRef) return;
  warmRef = next.id;
  /* Off the critical path: the current paint and the first input must not wait on this. */
  setTimeout(function () {
    var image = new Image();
    image.src = visibleCut(next);
    if (typeof image.decode === "function") image.decode().catch(function () {});
  }, 250);
}

/** Publish one wallpaper and immersion: URLs, accent, solved glass, tokens. */
function paint() {
  var wallpaper = WALLPAPERS[state.index];
  if (wallpaper === undefined || typeof document === "undefined") return;
  var root = document.documentElement;
  root.style.setProperty("--dsh-amiya-wide-image", 'url("' + ROUTE + "/" + wallpaper.wide + '")');
  root.style.setProperty("--dsh-amiya-narrow-image", 'url("' + ROUTE + "/" + wallpaper.narrow + '")');
  root.style.setProperty("--dsh-amiya-lqip", 'url("' + wallpaper.lqip + '")');
  root.style.setProperty("--dsh-amiya-accent", wallpaper.accent);
  root.setAttribute("data-dsh-amiya-wallpaper", wallpaper.id);
  applyVeil(wallpaper, state.immersion);
  applyTokens(wallpaper, state.immersion);
}

/** Retract everything paint wrote. */
function unpaintWallpaper() {
  if (typeof document === "undefined") return;
  var root = document.documentElement;
  root.style.removeProperty("--dsh-amiya-wide-image");
  root.style.removeProperty("--dsh-amiya-narrow-image");
  root.style.removeProperty("--dsh-amiya-lqip");
  var inkSuffixes = ["", "-2", "-3", "-4"];
  for (var i = 0; i < inkSuffixes.length; i += 1) {
    root.style.removeProperty("--dsh-amiya-ink" + inkSuffixes[i]);
    root.style.removeProperty("--dsh-amiya-ink" + inkSuffixes[i] + "-l");
  }
  root.style.removeProperty("--dsh-amiya-accent");
  root.removeAttribute("data-dsh-amiya-wallpaper");
  if (tokenDisposer !== null) {
    tokenDisposer();
    tokenDisposer = null;
  }
}

/* --- store --------------------------------------------------------------- */

function setState(patch) {
  state = Object.assign({}, state, patch);
  listeners.forEach(function (listener) {
    listener();
  });
}

/** Switch wallpaper, announcing it everywhere it is shown. */
function select(index) {
  var count = WALLPAPERS.length;
  var next = ((index % count) + count) % count;
  setState({ index: next });
  /* Written before painting: the choice must survive a reload even if the paint throws. */
  persistIndex(next);
  paint();
  warmNeighbour();
}

/**
 * Move one wallpaper forward or back, wrapping.
 *
 * Selecting and stepping are deliberately separate controls: the picker button
 * answers "which picture do I want", this one answers "next".
 */
function step(delta) {
  select(state.index + delta);
}

/**
 * Set the immersion dial and repaint. Only the small glass tag is rewritten
 * here, which is what keeps dragging the slider smooth.
 */
function setImmersion(value) {
  var next = Math.min(100, Math.max(0, Math.round(value)));
  if (next === state.immersion) return;
  setState({ immersion: next });
  paint();
  writeStored(IMMERSION_KEY, next);
}

/** Open or close the picker from anywhere. */
function togglePicker() {
  setState({ open: !state.open });
}

/** Subscribe a component to the store and return the current snapshot. */
function useStore() {
  var pair = React.useState(0);
  var force = pair[1];
  React.useEffect(function () {
    var listener = function () {
      force(function (value) {
        return value + 1;
      });
    };
    listeners.add(listener);
    return function () {
      listeners.delete(listener);
    };
  }, []);
  return state;
}

/**
 * Select the registered dark theme once, so the Arknights palette is what the
 * skin is composed against. A stored flag means a later manual choice is never
 * fought: the skin stays palette-aware either way, it just stops steering.
 */
function selectThemeOnce(theme) {
  var already = null;
  try {
    already = window.localStorage.getItem(THEME_CHOICE_KEY);
  } catch (error) {
    return;
  }
  if (already === "1") return;
  try {
    if (theme.getTheme().active.id !== THEME_ID) theme.setTheme(THEME_ID);
    window.localStorage.setItem(THEME_CHOICE_KEY, "1");
  } catch (error) {
    /* The theme id is unregistered or the write was refused; nothing to do. */
  }
}

